def replace_params(
    path: str,
    param_convertors: dict[str, Convertor[typing.Any]],
    path_params: dict[str, str],
) -> tuple[str, dict[str, str]]:
    for key, convertor in list(param_convertors.items()):
        value = path_params[key]
        if not isinstance(value, str):
